{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE hox_db.maplemonk.HOX_DB_YFLHOME_PAYMENT_RECON_CONSOLIDATED_2026 AS with cod_orders as (SELECT * FROM hox_db.maplemonk.payment_recon_easyecom where lower(mp_name)= \'shopify\' and cancelled_at is null and lower(payment_mode) = \'cod\'), clickpost as ( SELECT order_id, clickpost_Status, courier_partner, payment_mode, SUM(Clickpost_Amount) AS Clickpost_Amount, SUM(Delhivery_Amount) AS Delhivery_Amount, SUM(ShadowFx_Amount) AS ShadowFx_Amount, SUM(Ekart_Amount) AS Ekart_Amount, LISTAGG(product_sku_code,\',\') AS \"Product SKU Code\", FROM ( SELECT distinct a.order_id, a.payment_mode, CASE WHEN UPPER(a.clickpost_unified_status) in (\'RTO-FAILED\',\'RTO-MARKED\',\'RTO-INTRANSIT\',\'RTO-DELIVERED\') THEN \'RTO\' WHEN UPPER(a.clickpost_unified_status) in (\'OUTFORPICKUP\',\'ORDERPLACED\') THEN \'OrderPlaced\' WHEN UPPER(a.clickpost_unified_status) in (\'FAILEDDELIVERY\',\'DESTINATIONHUBIN\') THEN \'InTransit\' ELSE a.clickpost_unified_status END AS clickpost_Status, IFNULL(CAST(REPLACE(a.cod_value,\',\',\'\') AS INT),0) as Clickpost_Amount, IFNULL(CAST(REPLACE(b.cod_amount,\',\',\'\') AS INT),0) as Delhivery_Amount, IFNULL(CAST(REPLACE(c.cod_amount,\',\',\'\') AS INT),0) ShadowFx_Amount, IFNULL(CAST(REPLACE(d.cod_amount,\',\',\'\') AS INT),0) Ekart_Amount, a.courier_partner, product_sku_code FROM HOX_DB.MAPLEMONK.payment_recon_clickpost a LEFT JOIN HOX_DB.MAPLEMONK.payment_recon_delhivery b on a.awb=b.waybill_number LEFT JOIN HOX_DB.MAPLEMONK.payment_recon_shadowfx c on a.awb=c.awb LEFT JOIN HOX_DB.MAPLEMONK.payment_recon_ekart d on a.awb=d.tracking_id ) AS x GROUP BY 1,2,3,4 ), cod_final as ( select co.order_id, co.payment_mode, co.order_date, round(sum(co.selling_price) over(partition by co.order_id),0) as total_paid, coalesce(co.shipping_status,co.order_status,clickpost.clickpost_status) as final_status, coalesce(clickpost.courier_partner,co.courier) as courier_partner, round(clickpost.Clickpost_Amount,0), round(clickpost.Delhivery_Amount,0), round(clickpost.ShadowFx_Amount,0), round(clickpost.Ekart_Amount,0), round(clickpost.Delhivery_Amount+clickpost.ShadowFx_Amount+clickpost.Ekart_Amount,0) as total_received from cod_orders co left join clickpost on co.order_id=clickpost.order_id ), Final_Report_Cod as ( SELECT DATE_TRUNC(\'month\',to_date(order_date, \'YYYY/MM/DD\')) AS month_start, courier_partner as payment_partner, round(sum(total_paid),0) as total_amount_cx_paid, round(sum(total_received),0) AS total_amount_received , round(sum(total_paid-total_received),0) AS TOTAL_DIFFFERENCE FROM cod_final WHERE COURIER_PARTNER IS NOT NULL and COURIER_PARTNER!=\'CASH\' AND UPPER(FINAL_STATUS) IN (\'DELIVERED\') GROUP BY 1,2 ORDER BY 1 DESC ), prepaid_orders as ( SELECT distinct * from ( SELECT distinct e.*, db.order_id as db_order_id, db.shadow_id, db.gateway, coalesce(e.shipping_status,e.order_status,clickpost.clickpost_status) as final_status FROM hox_db.maplemonk.payment_recon_easyecom e left join hox_db.maplemonk.payment_recon_db db on concat(\'#\',e.order_id)=db.name left join clickpost on e.order_date=clickpost.order_id where lower(e.mp_name)= \'shopify\' and e.cancelled_at is null and lower(e.payment_mode) = \'prepaid\' ) as x where x.db_order_id is not null ), prepaid_orders_base as ( select order_date, db_order_id, shadow_id, gateway, round(sum(selling_price),0) as total_paid, listagg(distinct final_status,\',\') as status, COUNT(distinct final_status) AS status_count from prepaid_orders group by 1,2,3,4 ), Simpl as (SELECT *, LEFT(c.order_id,LENGTH(c.order_id)-LEN(\'-1\')) AS pre_final_shadowId, RIGHT(pre_final_shadowId,LENGTH(LEFT(c.order_id,LENGTH(c.order_id)-LENGTH(\'-1\')))-LENGTH(\'houseofx-\')) as final_shadow_Id FROM HOX_DB.MAPLEMONK.payment_recon_simpl c ), prepaid_final as ( select po.*, round(IFNULL(CAST(REPLACE(b.Total_Transaction_Amount,\',\',\'\') AS INT),0),0) as PhonePe_amount, round(IFNULL(CAST(REPLACE(c.net_amount_rs_,\',\',\'\') AS INT),0),0) as Simpl_amount, round(IFNULL(CAST(REPLACE(s.settlement_value,\',\',\'\') AS INT),0),0) as snapmint_amount FROM prepaid_orders_base po LEFT JOIN HOX_DB.MAPLEMONK.payment_recon_phonepe b on po.shadow_id=b.final_shadow_Id LEFT JOIN Simpl c on po.shadow_id=c.final_shadow_Id LEFT JOIN HOX_DB.MAPLEMONK.PAYMENT_RECON_SNAPMINT s on po.shadow_id=s.order_no_ ), Final_Report_Prepaid as ( SELECT *, cx_paid-total_received AS DIFFERENCE FROM ( SELECT DATE_TRUNC(\'month\', to_date(order_date, \'YYYY/MM/DD\')) AS month_start, gateway as payment_gateway, sum(total_paid) as cx_paid, sum(PhonePe_amount+Simpl_amount+snapmint_amount) as total_received FROM prepaid_final WHERE gateway IS NOT NULL and upper(gateway) !=\'CASH\' and status_count<=1 GROUP BY 1,2 ORDER BY 1 DESC ) AS x ) select * from final_report_prepaid union all select * from final_report_cod order by 1 desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from HOX_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            